  .product-grid-4 > .pcard:nth-child(4) { display: none; }
  .product-grid-3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .utility .hide-md { display: none; }
  .logo-tag { display: none; }
  .reviews-layout { grid-template-columns: 280px minmax(0, 1fr); gap: 32px; }
  .review-grid { grid-template-columns: minmax(0, 1fr); }
  .review-grid > .review:nth-child(n+3) { display: none; }
  .topic-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .principle-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cart-layout { grid-template-columns: minmax(0, 1fr) 340px; gap: 32px; }
  .checkout-layout { grid-template-columns: minmax(0, 1fr) 340px; gap: 32px; }
  .dash-showcase .dash { font-size: 13px; }
}

