  .mini-qty { font-weight: 700; }
  .faq-layout { grid-template-columns: minmax(0, 1fr); gap: 24px; }
  .faq-side { position: static; }
  .faq-cats { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
  .faq-cats::-webkit-scrollbar { display: none; }
  .faq-cat { width: auto; white-space: nowrap; border: 1.5px solid var(--border); }
  .faq-cat.is-active { border-color: var(--navy); }
  .faq-side .help-card { display: none; }
  .combo { grid-template-columns: minmax(0, 1fr); }
